import * as React from 'react'
import { PageParamsProvider as PageParamsProvider__ } from '@plasmicapp/react-web/lib/host'
import GlobalContextsProvider from '../components/plasmic/hypernova_inc/PlasmicGlobalContextsProvider'

import { PlasmicHomepage } from '../components/plasmic/hypernova_inc/PlasmicHomepage'
import dynamic from 'next/dynamic'
import Head from 'next/head'
import { useRouter } from 'next/router'

const ThreeAstronaut = dynamic(() => import('../components/ThreeAstronaut'), { ssr: false })

function Homepage() {
  const [isMobile, setIsMobile] = React.useState(false)
  const [shouldMountThree, setShouldMountThree] = React.useState(false)
  const [threeReady, setThreeReady] = React.useState(false)

  React.useEffect(() => {
    // Read the pre-paint assignment from _app.tsx. This avoids any visible "switch".
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const v = (window as any)?.__ASTRONAUT_VARIANT__
    if (v === 'threejs') {
      setShouldMountThree(true)
    }
  }, [])

  React.useEffect(() => {
    const checkMobile = () => {
      setIsMobile(window.innerWidth <= 1024)
    }
    checkMobile()
    window.addEventListener('resize', checkMobile)
    return () => window.removeEventListener('resize', checkMobile)
  }, [])

  return (
    <GlobalContextsProvider>
      <PageParamsProvider__ route={useRouter()?.pathname} params={useRouter()?.query} query={useRouter()?.query}>
        {/* Always preload the static hero background; we may hide/show via CSS gating. */}
        <Head>
          <link rel='preload' as='image' href='/plasmic/hypernova_inc/images/frame272Png.png' />
        </Head>

        {shouldMountThree ? (
          <Head>
            {/* Prioritize hero background images to avoid any pixelated-upscale while decoding. */}
            <link
              rel='preload'
              as='image'
              href='/plasmic/hypernova_inc/images/frame2111Png.png'
              fetchPriority='high'
              media='(min-width: 1025px)'
            />
            <link
              rel='preload'
              as='image'
              href='/plasmic/hypernova_inc/images/astronautPng.png'
              fetchPriority='high'
              media='(max-width: 1024px)'
            />
            <link
              rel='preload'
              as='image'
              href='/plasmic/hypernova_inc/images/image11.png'
              fetchPriority='high'
              media='(min-width: 1025px)'
            />

            {/* De-prioritize ThreeJS payload slightly so hero background wins the race. */}
            <link rel='prefetch' as='fetch' crossOrigin='anonymous' href='/source/Walking%20astronaut.glb' />
            <link rel='prefetch' as='image' href='/textures/gltf_embedded_0.png' />
            <link rel='prefetch' as='image' href='/textures/gltf_embedded_1.png' />
            <link rel='prefetch' as='image' href='/textures/gltf_embedded_2.png' />
            <link rel='prefetch' as='image' href='/textures/gltf_embedded_4.png' />
          </Head>
        ) : null}

        <PlasmicHomepage
          overrides={{
            // Keep DOM stable; CSS gating hides this when the threejs variant is active.
            transparentAstronaut: {
              props: {
                className: 'hn-static-astronaut',
              } as any,
            },
            // Make sure hero background images are not lazy-loaded on the homepage.
            og: {
              props: {
                loading: 'eager',
              } as any,
            },
            radialGradient: {
              props: {
                loading: 'eager',
              } as any,
            },
            hero: {
              wrap: (node) => (
                <div
                  data-astronaut-tracking-zone='hero'
                  style={{
                    position: 'relative',
                    overflow: 'visible',
                    width: '100%',
                    height: isMobile ? 'auto' : '100%',
                    overflowX: isMobile ? 'clip' : undefined,
                  }}>
                  {node}

                  {/* Keep a stable stage container; CSS hides it for the static variant. */}
                  {isMobile ? (
                    <div
                      className='hn-threejs-stage'
                      data-three-ready={threeReady ? 'true' : 'false'}
                      style={{
                        position: 'relative',
                        width: '100vw',
                        marginLeft: 'calc(50% - 50vw)',
                        height: 'clamp(420px, 60vh, 600px)',
                        pointerEvents: 'none',
                        zIndex: 10,
                        overflow: 'hidden',
                        WebkitMaskImage: 'linear-gradient(to bottom, black 70%, transparent 100%)',
                        maskImage: 'linear-gradient(to bottom, black 70%, transparent 100%)',
                      }}>
                      {shouldMountThree ? <ThreeAstronaut onReady={() => setThreeReady(true)} isMobile /> : null}
                    </div>
                  ) : (
                    <div
                      className='hn-threejs-stage'
                      data-three-ready={threeReady ? 'true' : 'false'}
                      style={{
                        position: 'absolute',
                        top: 0,
                        left: '40%',
                        right: 0,
                        bottom: 0,
                        width: '60%',
                        height: '100%',
                        pointerEvents: 'none',
                        zIndex: 10,
                        overflow: 'visible',
                      }}>
                      {shouldMountThree ? <ThreeAstronaut onReady={() => setThreeReady(true)} /> : null}
                    </div>
                  )}
                </div>
              ),
            },
            // Keep the next section above the astronaut spillover so it doesn't cover/capture clicks.
            services: {
              wrap: (node) => (isMobile ? node : <div style={{ position: 'relative', zIndex: 20 }}>{node}</div>),
            },
          }}
        />
      </PageParamsProvider__>
    </GlobalContextsProvider>
  )
}

export default Homepage
